pub inline fn call(self: @This(), comptime fn_name: []const u8, args_without_this: anytype, comptime Ret: type) Ret {
            _ = @setEvalBranchQuota(1000000);
            inline for (type_map) |entry| {
                if ((self.repr.data == (if (@typeInfo(@TypeOf(entry)) == .@"enum") @intFromEnum(entry) else entry.value))) {
                    const pointer = self.as(entry.ty);
                    const func = (&@field(entry.ty, fn_name));
                    var args: std.meta.ArgsTuple(@TypeOf(@field(entry.ty, fn_name))) = undefined;
                    _ = &args;
                    @field(args, "0") = pointer;
                    comptime var i: usize = 1;
                    _ = &i;
                    inline for (args_without_this) |a| {
                        @field(args, std.fmt.comptimePrint("{}", .{ i })) = a;
                        i = (i + 1);
                    }
                    return @call(.auto, func, args);
                }
            }
            _ = @panic("Invalid tag");
    }
    pub const Tag = TagType;
    pub const TagInt = TaggedPointer.Tag;
    pub const type_map: TypeMap(Types) = result.ty_map;
    pub const Null: @This() = initNull();
    const This = @This();
};
}
